(4781381, 690431, 63750, '<td valign="top">Nice idea, but the desat doesn''t quite feel right for some reason.</td>', 'Nice idea, but the desat doesn''t quite feel right for some reason.', '2008-06-23 10:46:42.000000', NULL, 1),
(4781386, 690535, 63750, '<td valign="top">Great composition, but a little dark.</td>', 'Great composition, but a little dark.', '2008-06-23 10:48:02.000000', NULL, 1),
