(4785653, 691014, 86447, '<td valign="top">This is wonderful!  The grain of the wood and that single round hardware add to the texture of the perfectly coiled rope.  Really a good setup.  Well done.</td>', 'This is wonderful!  The grain of the wood and that single round hardware add to the texture of the perfectly coiled rope.  Really a good setup.  Well done.', '2008-06-25 17:43:44.000000', NULL, 1),
(4785654, 690747, 86447, '<td valign="top">Gee!  I can''t IMAGINE how many times it took to get this so perfect.<br/> <br/>I think the background takes away from the brilliant idea a tad bit.  The rain reflections add it back in, though.<br/>Well done!</td>', 'Gee!  I can''t IMAGINE how many times it took to get this so perfect. I think the background takes away from the brilliant idea a tad bit.  The rain reflections add it back in, though.Well done!', '2008-06-25 17:44:00.000000', NULL, 1),
(4785655, 690886, 86447, '<td valign="top">Beautiful.  The colors and the idea are wonderful.<br/> <br/>The graininess might have been able to clear up a tad in Neat Image?  Well done.</td>', 'Beautiful.  The colors and the idea are wonderful. The graininess might have been able to clear up a tad in Neat Image?  Well done.', '2008-06-25 17:44:05.000000', NULL, 1),
(4785656, 690967, 86447, '<td valign="top">FABULOUS colors!  Really good idea.</td>', 'FABULOUS colors!  Really good idea.', '2008-06-25 17:44:08.000000', NULL, 1),
(4785669, 689983, 86447, '<td valign="top">"Create a photo in which a single line of some sort is the subject."  The subject seems to be the "2".<br/>I know there''s a single line inside of it... but combining it with all of the other lines in the image, it just doesn''t seem to have a single line as the subject, IMO.  Well shot, though.</td>', '"Create a photo in which a single line of some sort is the subject."  The subject seems to be the "2".I know there''s a single line inside of it... but combining it with all of the other lines in the image, it just doesn''t seem to have a single line as the subject, IMO.  Well shot, though.', '2008-06-25 17:48:18.000000', NULL, 1),
(4785670, 691082, 86447, '<td valign="top">Good idea! I think the reflections on the candies are a bit too blown to be really a high scorer, though.   The colors are fun!</td>', 'Good idea! I think the reflections on the candies are a bit too blown to be really a high scorer, though.   The colors are fun!', '2008-06-25 17:48:26.000000', NULL, 1),
(4785671, 690990, 86447, '<td valign="top">The "single line" here, to me, is unclear.  The runners aren''t in a single line  and the yellow line can''t be followed since it runs out of the image.   The only line left that I see is the edge of the road and I can''t call that the "subject" as the challenge requires.  I also think it could be more sharply in focus.   But, I like the idea of it.</td>', 'The "single line" here, to me, is unclear.  The runners aren''t in a single line  and the yellow line can''t be followed since it runs out of the image.   The only line left that I see is the edge of the road and I can''t call that the "subject" as the challenge requires.  I also think it could be more sharply in focus.   But, I like the idea of it.', '2008-06-25 17:48:30.000000', NULL, 1),
(4785672, 690445, 86447, '<td valign="top">I like the idea of this very much.  Adorable!   <br/>I think it could be a bit more in focus, especially the line, since that is what the challenge requires as the subject.  I don''t think I would have cut off the dog''s ears... but his shadow is fun!</td>', 'I like the idea of this very much.  Adorable!   I think it could be a bit more in focus, especially the line, since that is what the challenge requires as the subject.  I don''t think I would have cut off the dog''s ears... but his shadow is fun!', '2008-06-25 17:48:34.000000', NULL, 1),
(4785673, 690939, 86447, '<td valign="top">The road as a line and the utility lines (the title) compete for the <br/>"single line" requirement of the subject of the challenge.  The sky is beautiful.</td>', 'The road as a line and the utility lines (the title) compete for the "single line" requirement of the subject of the challenge.  The sky is beautiful.', '2008-06-25 17:48:36.000000', NULL, 1),
(4785675, 690753, 86447, '<td valign="top">This is ADORABLE.  The subject of the photo doesn''t seem to be a single line, more like an adorable kid, though.<br/>"Create a photo in which a single line of some sort is the main subject"</td>', 'This is ADORABLE.  The subject of the photo doesn''t seem to be a single line, more like an adorable kid, though."Create a photo in which a single line of some sort is the main subject"', '2008-06-25 17:49:01.000000', NULL, 1),
(4785679, 690964, 86447, '<td valign="top">The composition and colors are wonderful.  Perhaps a bit more DOF would make this score higher?  <br/>A fun idea!</td>', 'The composition and colors are wonderful.  Perhaps a bit more DOF would make this score higher?  A fun idea!', '2008-06-25 17:50:03.000000', NULL, 1),
(4785680, 691062, 86447, '<td valign="top">This could be more sharply in focus and score higher, I think.   I like the composition and colors.</td>', 'This could be more sharply in focus and score higher, I think.   I like the composition and colors.', '2008-06-25 17:50:09.000000', NULL, 1),
(4785681, 690597, 86447, '<td valign="top">"Create a photo in which a single line of some sort is the main subject"<br/>I like this photo very much, but it doesn''t meet the challenge, IMO.   There are many lines, and not one stands out as the subject.  <br/>The waviness of them is terrific, though.</td>', '"Create a photo in which a single line of some sort is the main subject"I like this photo very much, but it doesn''t meet the challenge, IMO.   There are many lines, and not one stands out as the subject.  The waviness of them is terrific, though.', '2008-06-25 17:50:14.000000', NULL, 1),
(4785726, 690882, 81885, '<td valign="top">Fantastic shot. Captures the theme perfectly. Well done.</td>', 'Fantastic shot. Captures the theme perfectly. Well done.', '2008-06-25 18:26:02.000000', NULL, 1),
(4785746, 690891, 85590, '<td valign="top">Love the tones, but would be better with focus closer to the clip!</td>', 'Love the tones, but would be better with focus closer to the clip!', '2008-06-25 18:50:24.000000', NULL, 1),
(4785854, 690998, 95013, '<td valign="top">wonderful!</td>', 'wonderful!', '2008-06-25 20:26:21.000000', NULL, 1),
(4785902, 690891, 50641, '<td valign="top">This is my favorite.  Love the acid tones and all the foggy blur.</td>', 'This is my favorite.  Love the acid tones and all the foggy blur.', '2008-06-25 21:35:01.000000', NULL, 1),
(4785903, 690970, 50641, '<td valign="top">Very nice take on the challenge.  Soothing image.</td>', 'Very nice take on the challenge.  Soothing image.', '2008-06-25 21:35:04.000000', NULL, 1),
(4785905, 691072, 50641, '<td valign="top">Nicely processed.</td>', 'Nicely processed.', '2008-06-25 21:35:34.000000', NULL, 1),
(4785940, 690947, 55837, '<td valign="top">I did this once (not the coke part, just the picture) and got the same double reflection on the mirror.  People said it was out of focus, but it''s not.</td>', 'I did this once (not the coke part, just the picture) and got the same double reflection on the mirror.  People said it was out of focus, but it''s not.', '2008-06-25 22:02:22.000000', NULL, 1),
(4785941, 691088, 55837, '<td valign="top">Cool.</td>', 'Cool.', '2008-06-25 22:02:29.000000', NULL, 1),
(4785943, 690971, 55837, '<td valign="top">1937 Chevy?  Just kidding.  My father would have known what it is.</td>', '1937 Chevy?  Just kidding.  My father would have known what it is.', '2008-06-25 22:03:14.000000', NULL, 1),
(4786093, 690440, 40819, '<td valign="top">Wonderful image. Just an amazing evening shot.</td>', 'Wonderful image. Just an amazing evening shot.', '2008-06-25 23:48:33.000000', NULL, 1),
(4786098, 690762, 40819, '<td valign="top">Love how simple and graceful this is.</td>', 'Love how simple and graceful this is.', '2008-06-25 23:50:09.000000', NULL, 1),
(4786103, 690887, 40819, '<td valign="top">I am old I remember that car. Nice work.</td>', 'I am old I remember that car. Nice work.', '2008-06-25 23:50:48.000000', NULL, 1),
(4786113, 691009, 40819, '<td valign="top">Touching. Higher score for emotional value then for photographic quality, but a very high score just the same. Excellent content.</td>', 'Touching. Higher score for emotional value then for photographic quality, but a very high score just the same. Excellent content.', '2008-06-25 23:54:16.000000', NULL, 1),
(4786167, 691108, 64446, '<td valign="top">Nice angle and perspective. Having her barefoot would make it even more interesting...</td>', 'Nice angle and perspective. Having her barefoot would make it even more interesting...', '2008-06-26 00:44:25.000000', NULL, 1),
(4786173, 690747, 64446, '<td valign="top">Very well done!</td>', 'Very well done!', '2008-06-26 00:47:59.000000', NULL, 1),
(4786192, 690971, 64446, '<td valign="top">Very nice! Love the abstract and the colors.</td>', 'Very nice! Love the abstract and the colors.', '2008-06-26 01:00:11.000000', NULL, 1),
(4786321, 690825, 76430, '<td valign="top">A little overused but nicely shot.  I like the sharpness, colors and lighting, which makes it look like brass or copper.</td>', 'A little overused but nicely shot.  I like the sharpness, colors and lighting, which makes it look like brass or copper.', '2008-06-26 02:48:25.000000', NULL, 1),
(4786332, 690076, 76430, '<td valign="top">Nice angle on the clothesline which fits the challenge well, though you sometimes hear a downward line has a negative connotation while an upward line (left to right) has a more positive connotation.  The right clothespin (peg if you''re from the other side of the ocean) is clipped off.  I''d shift over or move the peg to the other side of the others.  It all looks a bit out of focus, though it may be the texture of the line making it look that way.</td>', 'Nice angle on the clothesline which fits the challenge well, though you sometimes hear a downward line has a negative connotation while an upward line (left to right) has a more positive connotation.  The right clothespin (peg if you''re from the other side of the ocean) is clipped off.  I''d shift over or move the peg to the other side of the others.  It all looks a bit out of focus, though it may be the texture of the line making it look that way.', '2008-06-26 02:57:24.000000', NULL, 1),
(4786342, 690965, 76430, '<td valign="top">I''m not sure the intent of the title.  Did the pink line change her life or is it a line she just heard from someone?  It looks like some movement in her fingers, indicating a reaction confirming the facial expression.</td>', 'I''m not sure the intent of the title.  Did the pink line change her life or is it a line she just heard from someone?  It looks like some movement in her fingers, indicating a reaction confirming the facial expression.', '2008-06-26 03:05:27.000000', NULL, 1),
(4786348, 691062, 76430, '<td valign="top">Sharp macro and good DOF.</td>', 'Sharp macro and good DOF.', '2008-06-26 03:08:41.000000', NULL, 1),
(4786352, 690440, 76430, '<td valign="top">Nice sharp shot of which, the Brooklyn Bridge?  Good exposure showing everything very clearly.  I like the starburst filter.</td>', 'Nice sharp shot of which, the Brooklyn Bridge?  Good exposure showing everything very clearly.  I like the starburst filter.', '2008-06-26 03:11:52.000000', NULL, 1),
(4786355, 690747, 76430, '<td valign="top">Well done light painting.  How did you manage to get the figures so well outlined?</td>', 'Well done light painting.  How did you manage to get the figures so well outlined?', '2008-06-26 03:16:14.000000', NULL, 1),
(4786359, 690934, 76430, '<td valign="top">I''d really like to see the entire kite in the picture.  Good angle and colors.</td>', 'I''d really like to see the entire kite in the picture.  Good angle and colors.', '2008-06-26 03:21:37.000000', NULL, 1),
(4786369, 689757, 76430, '<td valign="top">Good cut-out and sharp shadow. I''m glad you got it validated.</td>', 'Good cut-out and sharp shadow. I''m glad you got it validated.', '2008-06-26 03:33:41.000000', NULL, 1),
(4786372, 690244, 76430, '<td valign="top">Very simple but I like it a lot.  The shadow continues the lead line.  Maybe just a tad OOF on the pencil, but hard to get sharp focus on both the line and pencil.</td>', 'Very simple but I like it a lot.  The shadow continues the lead line.  Maybe just a tad OOF on the pencil, but hard to get sharp focus on both the line and pencil.', '2008-06-26 03:35:58.000000', NULL, 1),
(4786496, 691036, 47852, '<td valign="top">Interesting take on the challenge.  Such a significant line that can make or break a game, and I like the motion captured.  Coloring seems a little flat to me.  A little more contrast or a soft light layer might help to really bring out the contrast of the red and green, as well as the white line.</td>', 'Interesting take on the challenge.  Such a significant line that can make or break a game, and I like the motion captured.  Coloring seems a little flat to me.  A little more contrast or a soft light layer might help to really bring out the contrast of the red and green, as well as the white line.', '2008-06-26 09:07:39.000000', NULL, 1),
(4786500, 690935, 47852, '<td valign="top">Great dof and I like the splash of interest in the background.  Light seems a little harsh, but I do like the contrast it creates.</td>', 'Great dof and I like the splash of interest in the background.  Light seems a little harsh, but I do like the contrast it creates.', '2008-06-26 09:09:12.000000', NULL, 1),
(4786516, 690983, 47852, '<td valign="top">Love the shallow dof here, and the bokeh it created in the background.  I like that you chose to crop so that the line is cut off on both sides, too.  There is something about the coloring which feels off, and unfortunately it''s the same thing I notice with my shots and never quite know how to fix without just fiddling with PS.  Nicely done though overall.</td>', 'Love the shallow dof here, and the bokeh it created in the background.  I like that you chose to crop so that the line is cut off on both sides, too.  There is something about the coloring which feels off, and unfortunately it''s the same thing I notice with my shots and never quite know how to fix without just fiddling with PS.  Nicely done though overall.', '2008-06-26 09:20:22.000000', NULL, 1),
(4786525, 691085, 47852, '<td valign="top">Love how you found one strong line to anchor the shot, with so many other lines throughout the shot.</td>', 'Love how you found one strong line to anchor the shot, with so many other lines throughout the shot.', '2008-06-26 09:25:31.000000', NULL, 1),
(4786531, 690945, 47852, '<td valign="top">Interesting idea, but unfortunately the processing is way too evident.</td>', 'Interesting idea, but unfortunately the processing is way too evident.', '2008-06-26 09:28:18.000000', NULL, 1),
(4786535, 691048, 47852, '<td valign="top">Great textures and contrast.  Wish the line was a bit more diagonal to really show that it was intentional.  Other than that, the shot doesn''t really have something to grab the viewer and hold their interest.  A unique angle would help, or adding something like a snail or a shadow of a bicycle tire would help to show "line rider" as the title says.</td>', 'Great textures and contrast.  Wish the line was a bit more diagonal to really show that it was intentional.  Other than that, the shot doesn''t really have something to grab the viewer and hold their interest.  A unique angle would help, or adding something like a snail or a shadow of a bicycle tire would help to show "line rider" as the title says.', '2008-06-26 09:31:01.000000', NULL, 1),
(4786536, 690464, 47852, '<td valign="top">Love how the single line of the garden hose draws your attention, yet the shot is full of lines of plants and markers.  Not sure about the blur at the bottom of the shot.. it seems to be a bit hazy and not just blurred.  I might have cropped a bit of that off.  Overall though, a nice job!</td>', 'Love how the single line of the garden hose draws your attention, yet the shot is full of lines of plants and markers.  Not sure about the blur at the bottom of the shot.. it seems to be a bit hazy and not just blurred.  I might have cropped a bit of that off.  Overall though, a nice job!', '2008-06-26 09:32:42.000000', NULL, 1),
(4786549, 690384, 47852, '<td valign="top">Simple, yet interesting.  I like the idea with this shot, but I''m not sure that the combination of all the elements works together.  With the inverted colors creating the black trail to look more like smoke, plane flying downward, and the grain, this shot leaves me with an uneasy feel that the plane is about to crash.  But, I do appreciate that you took a shot of a plane, which is a pretty common sight, and did something unique with it.</td>', 'Simple, yet interesting.  I like the idea with this shot, but I''m not sure that the combination of all the elements works together.  With the inverted colors creating the black trail to look more like smoke, plane flying downward, and the grain, this shot leaves me with an uneasy feel that the plane is about to crash.  But, I do appreciate that you took a shot of a plane, which is a pretty common sight, and did something unique with it.', '2008-06-26 09:40:10.000000', NULL, 1),
(4786558, 690893, 47852, '<td valign="top">Great idea do do a skyline and you have a nice contrast here.  You have some interesting shapes in the skyline, but perhaps a tighter crop would have shown those off a bit more, and also focused in more on those bold colors in the sky.</td>', 'Great idea do do a skyline and you have a nice contrast here.  You have some interesting shapes in the skyline, but perhaps a tighter crop would have shown those off a bit more, and also focused in more on those bold colors in the sky.', '2008-06-26 09:44:03.000000', NULL, 1),
(4786560, 690597, 47852, '<td valign="top">Great series of lines to create an abstract pattern, but I wish one stood out as the main focal point.</td>', 'Great series of lines to create an abstract pattern, but I wish one stood out as the main focal point.', '2008-06-26 09:44:45.000000', NULL, 1),
(4786572, 691047, 47852, '<td valign="top">Nice b/w conversion here, and the variety of designs and patterns really comes through nicely with the lighting.  I also like the use of negative space at the bottom.  I''m not as sure about the vignette though.  It almost makes it look like there are aliens beaming down to steal the aprons! :P  Great shot though! :)</td>', 'Nice b/w conversion here, and the variety of designs and patterns really comes through nicely with the lighting.  I also like the use of negative space at the bottom.  I''m not as sure about the vignette though.  It almost makes it look like there are aliens beaming down to steal the aprons! :P  Great shot though! :)', '2008-06-26 09:49:10.000000', NULL, 1),
(4786574, 690967, 47852, '<td valign="top">Unique take on the challenge, but with the contrasting colors and the darkness on the left, the yellowish line really comes across nicely.  Great job!</td>', 'Unique take on the challenge, but with the contrasting colors and the darkness on the left, the yellowish line really comes across nicely.  Great job!', '2008-06-26 09:49:40.000000', NULL, 1),
(4786577, 690497, 47852, '<td valign="top">Fun shot!  That blue really pops!  I like the more subtle blue of the shirt to match the line but not compete with it.  My only nitpick is that the line isn''t completely horizontal.</td>', 'Fun shot!  That blue really pops!  I like the more subtle blue of the shirt to match the line but not compete with it.  My only nitpick is that the line isn''t completely horizontal.', '2008-06-26 09:49:48.000000', NULL, 1),
(4786581, 690882, 47852, '<td valign="top">So much going on here... the shoreline and contrail creating the parallel lines of thirds, the clear reflections, lines of the trees.  Wow.  And you even got the moon in there.  Very nice!</td>', 'So much going on here... the shoreline and contrail creating the parallel lines of thirds, the clear reflections, lines of the trees.  Wow.  And you even got the moon in there.  Very nice!', '2008-06-26 09:50:40.000000', NULL, 1),
(4786583, 690199, 47852, '<td valign="top">Great dof, and I love how the curve of the plant fits so nicely in the frame.  Well done!</td>', 'Great dof, and I love how the curve of the plant fits so nicely in the frame.  Well done!', '2008-06-26 09:50:50.000000', NULL, 1),
(4786651, 690761, 65592, '<td valign="top">The crop you choose does not work here IMO. I thing a vertical or even squared crop would be better. Also i would like to see a more agressive close up on the caterpillar.</td>', 'The crop you choose does not work here IMO. I thing a vertical or even squared crop would be better. Also i would like to see a more agressive close up on the caterpillar.', '2008-06-26 10:44:53.000000', NULL, 1),
(4786721, 690985, 50695, '<td valign="top">nice composition</td>', 'nice composition', '2008-06-26 11:58:05.000000', NULL, 1),
(4786737, 690825, 94889, '<td valign="top">Perfect Straight Line</td>', 'Perfect Straight Line', '2008-06-26 12:19:35.000000', NULL, 1),
(4786778, 690698, 63398, '<td valign="top">This is just an exquisite image! Terrific composition, colors, lighting......I love your take on the challenge with this! 8</td>', 'This is just an exquisite image! Terrific composition, colors, lighting......I love your take on the challenge with this! 8', '2008-06-26 12:58:27.000000', NULL, 1),
(4786780, 690758, 63398, '<td valign="top">Nice color, concept, and DOF. 6</td>', 'Nice color, concept, and DOF. 6', '2008-06-26 12:59:09.000000', NULL, 1),
(4786783, 691033, 63398, '<td valign="top">Good meld of phrase with the image....nice clean image in context. Terrific prespective. 7</td>', 'Good meld of phrase with the image....nice clean image in context. Terrific prespective. 7', '2008-06-26 13:00:58.000000', NULL, 1),
(4786784, 690625, 63398, '<td valign="top">AWESOME!!! Creative, striking, intriguing......I''m out of superlatives!!! 10</td>', 'AWESOME!!! Creative, striking, intriguing......I''m out of superlatives!!! 10', '2008-06-26 13:02:06.000000', NULL, 1),
(4786786, 690076, 63398, '<td valign="top">Excellent minimalist offering. I like the clean vibrant, yet subdued colors. Nice take on the challenge description.....good title. 7</td>', 'Excellent minimalist offering. I like the clean vibrant, yet subdued colors. Nice take on the challenge description.....good title. 7', '2008-06-26 13:03:43.000000', NULL, 1),
(4786787, 690947, 63398, '<td valign="top">Gritty.....emotive.....scary.....very well done, albeit sobering and an unpleasant dose of reality. Extra point for gutsy. 8</td>', 'Gritty.....emotive.....scary.....very well done, albeit sobering and an unpleasant dose of reality. Extra point for gutsy. 8', '2008-06-26 13:05:25.000000', NULL, 1),
(4786789, 690946, 63398, '<td valign="top">Terrific interpretation, great capture! 7</td>', 'Terrific interpretation, great capture! 7', '2008-06-26 13:06:19.000000', NULL, 1),
(4786792, 690262, 63398, '<td valign="top">Excellent capture! Pretty sky! 6</td>', 'Excellent capture! Pretty sky! 6', '2008-06-26 13:07:53.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4786794, 691079, 63398, '<td valign="top">I really like this entry, though with Advanced editing, I''d have liked to at least seen that sign burned some so as not to be so distracting. Maybe even a tilted crop.......just musing....good composition. 6</td>', 'I really like this entry, though with Advanced editing, I''d have liked to at least seen that sign burned some so as not to be so distracting. Maybe even a tilted crop.......just musing....good composition. 6', '2008-06-26 13:09:33.000000', NULL, 1),
(4786796, 690879, 63398, '<td valign="top">Nicely done concept and execution. Love the high contrast. 7</td>', 'Nicely done concept and execution. Love the high contrast. 7', '2008-06-26 13:10:15.000000', NULL, 1),
(4786798, 690713, 63398, '<td valign="top">Fun and creative.....love the minimalism. 7</td>', 'Fun and creative.....love the minimalism. 7', '2008-06-26 13:10:55.000000', NULL, 1),
