(4786803, 690971, 63398, '<td valign="top">Like the title, like the image......the fender welt detracts from the single line of the chrome strip.....or the chrome strip detracts from the single line of the fender welt?????.....8&gt;).....6</td>', 'Like the title, like the image......the fender welt detracts from the single line of the chrome strip.....or the chrome strip detracts from the single line of the fender welt?????.....8>).....6', '2008-06-26 13:13:50.000000', NULL, 1),
(4786806, 691082, 63398, '<td valign="top">Good concept, love the minimalism.....well done. 7</td>', 'Good concept, love the minimalism.....well done. 7', '2008-06-26 13:14:49.000000', NULL, 1),
(4786810, 691115, 63398, '<td valign="top">Interesting, creative, and unique in presentation.....are the eggs wet? Varnished???? Love the tilt! 8</td>', 'Interesting, creative, and unique in presentation.....are the eggs wet? Varnished???? Love the tilt! 8', '2008-06-26 13:15:48.000000', NULL, 1),
(4786816, 690985, 63398, '<td valign="top">Very clean image.....good perspective, nice the way the line dominates the image. 7</td>', 'Very clean image.....good perspective, nice the way the line dominates the image. 7', '2008-06-26 13:19:20.000000', NULL, 1),
(4786818, 690976, 63398, '<td valign="top">Beautiful scene divided nicely by the fenceline. 7</td>', 'Beautiful scene divided nicely by the fenceline. 7', '2008-06-26 13:20:22.000000', NULL, 1),
(4786819, 691108, 63398, '<td valign="top">The angle, DOF, and perspective make this image! 7</td>', 'The angle, DOF, and perspective make this image! 7', '2008-06-26 13:20:50.000000', NULL, 1),
