(4789491, 690970, 76335, '<td valign="top">Very abstract but well executed. Good job!</td>', 'Very abstract but well executed. Good job!', '2008-06-28 21:25:16.000000', NULL, 1),
(4789493, 690964, 76335, '<td valign="top">Would like to have seen this cropped or composed such that you couldn''t see the end of the line. Good idea though; I like the colors.</td>', 'Would like to have seen this cropped or composed such that you couldn''t see the end of the line. Good idea though; I like the colors.', '2008-06-28 21:25:59.000000', NULL, 1),
(4789494, 691073, 76335, '<td valign="top">Indeed. Very dramatic. Original idea.</td>', 'Indeed. Very dramatic. Original idea.', '2008-06-28 21:26:28.000000', NULL, 1),
(4789496, 690076, 76335, '<td valign="top">Good use of negative space, thirds. I like the colors.</td>', 'Good use of negative space, thirds. I like the colors.', '2008-06-28 21:26:55.000000', NULL, 1),
