INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4789581, 691014, 15291, '<td valign="top">Simple &amp; effective, The composition &amp; tonality are very well done.</td>', 'Simple & effective, The composition & tonality are very well done.', '2008-06-28 23:01:39.000000', NULL, 1),
(4789630, 690584, 66524, '<td valign="top">Very creative take on the challenge.</td>', 'Very creative take on the challenge.', '2008-06-28 23:57:53.000000', NULL, 1),
(4789631, 690991, 66524, '<td valign="top">indeed a one liner!  I love it!</td>', 'indeed a one liner!  I love it!', '2008-06-29 00:00:12.000000', NULL, 1),
(4789654, 690514, 24896, '<td valign="top">I wonder if you had a photo buddy taking this shot? and I wonder if you are the legs in the other photo? But, would that mean the penny took the other picture of the legs!?!? Im confused now! Still a great single line good luck.</td>', 'I wonder if you had a photo buddy taking this shot? and I wonder if you are the legs in the other photo? But, would that mean the penny took the other picture of the legs!?!? Im confused now! Still a great single line good luck.', '2008-06-29 00:40:40.000000', NULL, 1),
(4789713, 690998, 9462, '<td valign="top">I take it no one ever told him "step on a crack and you''ll break your Momma''s back"<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=670651" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670651.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670651.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670651.jpg"/></a></td>', 'I take it no one ever told him "step on a crack and you''ll break your Momma''s back"', '2008-06-29 02:02:49.000000', NULL, 1),
(4789728, 690699, 76335, '<td valign="top">Great subject, vantage point. Would like to have seen more DOF.</td>', 'Great subject, vantage point. Would like to have seen more DOF.', '2008-06-29 02:24:23.000000', NULL, 1),
(4789729, 690800, 76335, '<td valign="top">Not terribly intriguing and the border doesn''t add anything. Also, seems oversturated.</td>', 'Not terribly intriguing and the border doesn''t add anything. Also, seems oversturated.', '2008-06-29 02:25:05.000000', NULL, 1),
(4789735, 691044, 76335, '<td valign="top">I like the DOF of this and the uncluttered background. Great perspective.</td>', 'I like the DOF of this and the uncluttered background. Great perspective.', '2008-06-29 02:26:43.000000', NULL, 1),
(4789818, 691048, 674, '<td valign="top">love the texture in this</td>', 'love the texture in this', '2008-06-29 05:47:30.000000', NULL, 1),
(4789819, 690490, 674, '<td valign="top">perhaps more depth of field? nice idea though</td>', 'perhaps more depth of field? nice idea though', '2008-06-29 05:49:11.000000', NULL, 1),
(4789828, 690963, 66494, '<td valign="top">I really really like this entry. Lots of lines, everywhere I looked. And all of them were fun too.</td>', 'I really really like this entry. Lots of lines, everywhere I looked. And all of them were fun too.', '2008-06-29 06:50:48.000000', NULL, 1),
(4789830, 689757, 66494, '<td valign="top">Very graphic, very fun, and a great idea to boot. 10.</td>', 'Very graphic, very fun, and a great idea to boot. 10.', '2008-06-29 06:58:50.000000', NULL, 1),
(4789863, 690825, 92907, '<td valign="top">I love the angle of the line, the colour and the lighting.  Great shot.</td>', 'I love the angle of the line, the colour and the lighting.  Great shot.', '2008-06-29 08:39:13.000000', NULL, 1),
(4789864, 691048, 92907, '<td valign="top">I like the texture and angle of the line. Simple composition,but effective.</td>', 'I like the texture and angle of the line. Simple composition,but effective.', '2008-06-29 08:40:22.000000', NULL, 1),
(4789865, 691061, 92907, '<td valign="top">Very nice...geat composition which brings the line to the centre of the picture.  Great clouds too.</td>', 'Very nice...geat composition which brings the line to the centre of the picture.  Great clouds too.', '2008-06-29 08:41:10.000000', NULL, 1),
(4789866, 691002, 92907, '<td valign="top">Nice landscape. My eye goes more to the mountains than the line in the road.</td>', 'Nice landscape. My eye goes more to the mountains than the line in the road.', '2008-06-29 08:42:22.000000', NULL, 1),
(4789867, 691062, 92907, '<td valign="top">I would have liked it to be a bit sharper, more focus...the texture of the rope is great.</td>', 'I would have liked it to be a bit sharper, more focus...the texture of the rope is great.', '2008-06-29 08:44:05.000000', NULL, 1),
(4789868, 690120, 92907, '<td valign="top">Blur seems to take away from the line effect.</td>', 'Blur seems to take away from the line effect.', '2008-06-29 08:45:31.000000', NULL, 1),
(4789869, 691023, 92907, '<td valign="top">Creative depiction of a line...nice picture</td>', 'Creative depiction of a line...nice picture', '2008-06-29 08:46:54.000000', NULL, 1),
(4789870, 691108, 92907, '<td valign="top">Great shot...I love the lighting.  Great angle.</td>', 'Great shot...I love the lighting.  Great angle.', '2008-06-29 08:48:27.000000', NULL, 1),
(4789871, 690273, 92907, '<td valign="top">I like the angle you took the shot from...nice effect.</td>', 'I like the angle you took the shot from...nice effect.', '2008-06-29 08:52:37.000000', NULL, 1),
(4789872, 690800, 92907, '<td valign="top">I like the composition and angle you shot this from...</td>', 'I like the composition and angle you shot this from...', '2008-06-29 08:53:48.000000', NULL, 1),
(4789873, 690076, 92907, '<td valign="top">Simple but effective.  I like the red, white and blue contrast.</td>', 'Simple but effective.  I like the red, white and blue contrast.', '2008-06-29 08:54:35.000000', NULL, 1),
(4789875, 690439, 92907, '<td valign="top">I like the composition.  The blue/aqua colour of the line is a bit bright for me.</td>', 'I like the composition.  The blue/aqua colour of the line is a bit bright for me.', '2008-06-29 08:56:18.000000', NULL, 1),
(4789876, 690888, 92907, '<td valign="top">Right side of picture a bit oof.</td>', 'Right side of picture a bit oof.', '2008-06-29 08:57:07.000000', NULL, 1),
(4789877, 690934, 92907, '<td valign="top">I would have liked to have seen more of the kite.</td>', 'I would have liked to have seen more of the kite.', '2008-06-29 08:58:20.000000', NULL, 1),
(4789880, 690397, 92907, '<td valign="top">Great shot.  I like the darkness of the clouds and background.  Good lighting on the sand emphasizes the line.</td>', 'Great shot.  I like the darkness of the clouds and background.  Good lighting on the sand emphasizes the line.', '2008-06-29 09:00:17.000000', NULL, 1),
(4789883, 690879, 92907, '<td valign="top">Great shot.  I will look forward to reading how you did that.</td>', 'Great shot.  I will look forward to reading how you did that.', '2008-06-29 09:02:00.000000', NULL, 1),
(4789885, 690380, 92907, '<td valign="top">Very entertaining.  Nice shot.</td>', 'Very entertaining.  Nice shot.', '2008-06-29 09:03:22.000000', NULL, 1),
(4789974, 690943, 50695, '<td valign="top">pretty</td>', 'pretty', '2008-06-29 11:31:30.000000', NULL, 1),
(4789976, 690970, 50695, '<td valign="top">lovely abstract</td>', 'lovely abstract', '2008-06-29 11:31:43.000000', NULL, 1),
(4789977, 690753, 50695, '<td valign="top">In painting we learned to create lines not by drawing them but by putting two different tones next to each other. You demonstrate that beautifully. In fact, the lines in line drawings are just illusions trying to simulate this effect.</td>', 'In painting we learned to create lines not by drawing them but by putting two different tones next to each other. You demonstrate that beautifully. In fact, the lines in line drawings are just illusions trying to simulate this effect.', '2008-06-29 11:31:45.000000', NULL, 1),
(4789980, 690886, 76335, '<td valign="top">Very original. I can''t help but wonder what it would have looked like with the line turned horizontal. I like the complementary colors.</td>', 'Very original. I can''t help but wonder what it would have looked like with the line turned horizontal. I like the complementary colors.', '2008-06-29 11:38:58.000000', NULL, 1),
(4789982, 690971, 76335, '<td valign="top">I had a similar idea for this challenge, but never got to our local car show -- the weather wasn''t right. Good job with this.</td>', 'I had a similar idea for this challenge, but never got to our local car show -- the weather wasn''t right. Good job with this.', '2008-06-29 11:40:43.000000', NULL, 1),
(4789986, 690891, 76335, '<td valign="top">Interesting DOF. It was bold to put the clothes pin just out of focus.</td>', 'Interesting DOF. It was bold to put the clothes pin just out of focus.', '2008-06-29 11:43:01.000000', NULL, 1),
(4789988, 690947, 76335, '<td valign="top">Harsh processing and disturbing subject, which I guess was the point. The crop is a little tight at the top.</td>', 'Harsh processing and disturbing subject, which I guess was the point. The crop is a little tight at the top.', '2008-06-29 11:44:14.000000', NULL, 1),
(4789989, 690823, 76335, '<td valign="top">Would like to have seen more bra and less border.</td>', 'Would like to have seen more bra and less border.', '2008-06-29 11:45:07.000000', NULL, 1),
(4789991, 690986, 76335, '<td valign="top">Nicely done. Great lighting and textures.</td>', 'Nicely done. Great lighting and textures.', '2008-06-29 11:46:00.000000', NULL, 1),
(4789992, 691088, 76335, '<td valign="top">Very original idea and well executed.</td>', 'Very original idea and well executed.', '2008-06-29 11:46:33.000000', NULL, 1),
(4789994, 690464, 76335, '<td valign="top">Good idea, but the focus seems soft and the processing harsh.</td>', 'Good idea, but the focus seems soft and the processing harsh.', '2008-06-29 11:47:06.000000', NULL, 1),
(4790030, 691109, 76335, '<td valign="top">Good idea, but it needs some context. The background is too dark.</td>', 'Good idea, but it needs some context. The background is too dark.', '2008-06-29 12:40:02.000000', NULL, 1),
(4790031, 690920, 76335, '<td valign="top">I love it. Well executed and great colors.</td>', 'I love it. Well executed and great colors.', '2008-06-29 12:40:17.000000', NULL, 1),
(4790036, 690991, 76335, '<td valign="top">Neat-o. Fits the challenge well. The lighting is just right.</td>', 'Neat-o. Fits the challenge well. The lighting is just right.', '2008-06-29 12:41:31.000000', NULL, 1),
(4790039, 690712, 76335, '<td valign="top">Long exposure against a night sky? Interesting.</td>', 'Long exposure against a night sky? Interesting.', '2008-06-29 12:42:16.000000', NULL, 1),
(4790045, 690597, 76335, '<td valign="top">Abstract. I like it. It looks like your <i>single</i> line (there are many) is the bolder one running diagonal from the top left. I hope that''s not lost on other voters. Good luck!</td>', 'Abstract. I like it. It looks like your single line (there are many) is the bolder one running diagonal from the top left. I hope that''s not lost on other voters. Good luck!', '2008-06-29 12:43:52.000000', NULL, 1),
(4790051, 691091, 76335, '<td valign="top">Abstract and kind of edgy. I like it. Not the strongest line per se (more of a circle) but this is neat.</td>', 'Abstract and kind of edgy. I like it. Not the strongest line per se (more of a circle) but this is neat.', '2008-06-29 12:46:06.000000', NULL, 1),
(4790054, 690753, 76335, '<td valign="top">Is the line the wall? That''s a stretch. Challenge aside, this is a fun shot -- great capture of expression and well executed.</td>', 'Is the line the wall? That''s a stretch. Challenge aside, this is a fun shot -- great capture of expression and well executed.', '2008-06-29 12:47:03.000000', NULL, 1),
(4790058, 690518, 76335, '<td valign="top">Well, it certainly meets the challenge. Not terribly interesting though.</td>', 'Well, it certainly meets the challenge. Not terribly interesting though.', '2008-06-29 12:47:29.000000', NULL, 1),
(4790060, 690497, 76335, '<td valign="top">Funny. Original. Reminds me of the masking tape guy from the recent "Masks" challenge.</td>', 'Funny. Original. Reminds me of the masking tape guy from the recent "Masks" challenge.', '2008-06-29 12:48:27.000000', NULL, 1),
(4790069, 690982, 76335, '<td valign="top">Seems to lean to the right a bit. Not sure how I feel about the colors. They''re unnatural, but have a strange appeal to them.</td>', 'Seems to lean to the right a bit. Not sure how I feel about the colors. They''re unnatural, but have a strange appeal to them.', '2008-06-29 12:54:19.000000', NULL, 1),
(4790074, 690584, 76335, '<td valign="top">Great framing, original, very well executed.</td>', 'Great framing, original, very well executed.', '2008-06-29 12:56:56.000000', NULL, 1),
(4790077, 691108, 76335, '<td valign="top">Unfortunate title (only because I''m about done voting and have seen it several times) but this might be my favorite of all the railroad shots. Original idea, well executed.</td>', 'Unfortunate title (only because I''m about done voting and have seen it several times) but this might be my favorite of all the railroad shots. Original idea, well executed.', '2008-06-29 12:57:57.000000', NULL, 1),
(4790078, 690963, 76335, '<td valign="top">I like the geometry. Good eye composing and capturing this.</td>', 'I like the geometry. Good eye composing and capturing this.', '2008-06-29 12:58:29.000000', NULL, 1),
(4790081, 690440, 76335, '<td valign="top">Great colors and good job exposing this.</td>', 'Great colors and good job exposing this.', '2008-06-29 12:59:37.000000', NULL, 1),
(4790086, 690888, 76335, '<td valign="top">Nice low key effect. I would have cropped out some of the blurred trees on the right.</td>', 'Nice low key effect. I would have cropped out some of the blurred trees on the right.', '2008-06-29 13:02:43.000000', NULL, 1),
(4790087, 690939, 76335, '<td valign="top">More DOF would have helped, I think.</td>', 'More DOF would have helped, I think.', '2008-06-29 13:03:53.000000', NULL, 1),
(4790089, 690887, 76335, '<td valign="top">The subtle tones here are beautiful. I think there might have been a more effective way to frame or compose this, but I''m not sure what it is. More of the tire? More acute angle? Very nice.</td>', 'The subtle tones here are beautiful. I think there might have been a more effective way to frame or compose this, but I''m not sure what it is. More of the tire? More acute angle? Very nice.', '2008-06-29 13:05:57.000000', NULL, 1),
(4790094, 690438, 76335, '<td valign="top">Light and dark, maybe, or clean and rough, but I''m not seeing anything particularly good or evil about either side. Title aside, this is well composed, executed and processed.</td>', 'Light and dark, maybe, or clean and rough, but I''m not seeing anything particularly good or evil about either side. Title aside, this is well composed, executed and processed.', '2008-06-29 13:10:55.000000', NULL, 1),
(4790095, 690762, 41357, '<td valign="top">I sure hope so</td>', 'I sure hope so', '2008-06-29 13:11:36.000000', NULL, 1),
(4790096, 690746, 76335, '<td valign="top">Not teribly intriguing. Needs something more to hold interest.</td>', 'Not teribly intriguing. Needs something more to hold interest.', '2008-06-29 13:11:46.000000', NULL, 1),
(4790099, 690431, 76335, '<td valign="top">Good use of selective desat. I might have used just a tad less saturation on the line.</td>', 'Good use of selective desat. I might have used just a tad less saturation on the line.', '2008-06-29 13:14:06.000000', NULL, 1),
(4790100, 690713, 76335, '<td valign="top">Fun. This might have been more interesting turned horizontal.</td>', 'Fun. This might have been more interesting turned horizontal.', '2008-06-29 13:15:01.000000', NULL, 1),
(4790101, 691072, 76335, '<td valign="top">Interesting processing. Very beautiful.</td>', 'Interesting processing. Very beautiful.', '2008-06-29 13:15:35.000000', NULL, 1),
(4790102, 690882, 76335, '<td valign="top">Subtle. Great idea. Well done.</td>', 'Subtle. Great idea. Well done.', '2008-06-29 13:15:51.000000', NULL, 1),
(4790105, 690934, 76335, '<td valign="top">Excellent use of negative space. Effective framing/crop too, showing just the tail of the kite.</td>', 'Excellent use of negative space. Effective framing/crop too, showing just the tail of the kite.', '2008-06-29 13:17:47.000000', NULL, 1),
(4790144, 690939, 27373, '<td valign="top">Lensbaby?? I like the "scale model" look of the image.</td>', 'Lensbaby?? I like the "scale model" look of the image.', '2008-06-29 14:07:46.000000', NULL, 1),
(4790161, 689510, 88136, '<td valign="top">trippy!</td>', 'trippy!', '2008-06-29 14:43:28.000000', NULL, 1),
(4790162, 690693, 21124, '<td valign="top">The bokeh (mirror lens?) is bothering me on this shot.</td>', 'The bokeh (mirror lens?) is bothering me on this shot.', '2008-06-29 14:43:57.000000', NULL, 1),
(4790163, 690891, 88136, '<td valign="top">umm... not sure i like the blurriness. fabulous idea though</td>', 'umm... not sure i like the blurriness. fabulous idea though', '2008-06-29 14:44:14.000000', NULL, 1),
(4790164, 690497, 88136, '<td valign="top">i love it when people do weird stuff like this:)</td>', 'i love it when people do weird stuff like this:)', '2008-06-29 14:44:46.000000', NULL, 1),
(4790168, 690998, 76335, '<td valign="top">Terrific! Minor quibble: I would like to have seen the line ahead of him directly over his head versus to the left. But this a great idea and well captured and processed. <br/> <br/>The next day: On second thought, I like it just the way it is. A nine for you.</td>', 'Terrific! Minor quibble: I would like to have seen the line ahead of him directly over his head versus to the left. But this a great idea and well captured and processed.  The next day: On second thought, I like it just the way it is. A nine for you.', '2008-06-29 14:57:20.000000', NULL, 1),
(4790169, 690974, 76335, '<td valign="top">Love this! The DOF is dead on and the contrasts and textures all add something. Very monolithic. A nine for you.</td>', 'Love this! The DOF is dead on and the contrasts and textures all add something. Very monolithic. A nine for you.', '2008-06-29 14:57:41.000000', NULL, 1),
(4790170, 690384, 76335, '<td valign="top">Beautiful! Contrail was my idea, but I never got around to it. I''m glad someone else had the idea and did a good job with it. I like the grain too. A nine for you.</td>', 'Beautiful! Contrail was my idea, but I never got around to it. I''m glad someone else had the idea and did a good job with it. I like the grain too. A nine for you.', '2008-06-29 14:57:52.000000', NULL, 1),
(4790171, 690397, 76335, '<td valign="top">Original and very nicely done. (I''m so ready for my beach vacation, so you''re probably getting an extra point or two from me.) Love the textures in the sand and the clouds. Good DOF too. A nine for you.</td>', 'Original and very nicely done. (I''m so ready for my beach vacation, so you''re probably getting an extra point or two from me.) Love the textures in the sand and the clouds. Good DOF too. A nine for you.', '2008-06-29 14:58:08.000000', NULL, 1),
(4790172, 691042, 76335, '<td valign="top">Great lighting and colors and perspective too. There''s a simple but harsh reality to this. No attempt to pretty it up or make it look like something it isn''t. Good job! An eight for you.</td>', 'Great lighting and colors and perspective too. There''s a simple but harsh reality to this. No attempt to pretty it up or make it look like something it isn''t. Good job! An eight for you.', '2008-06-29 14:58:15.000000', NULL, 1),
(4790173, 691064, 76335, '<td valign="top">Abstract and edgy. Chilling even. The title helps tell the story. I like this a lot. An eight for you.</td>', 'Abstract and edgy. Chilling even. The title helps tell the story. I like this a lot. An eight for you.', '2008-06-29 14:58:25.000000', NULL, 1),
(4790174, 690959, 76335, '<td valign="top">This is terrific. Well composed, good DOF too. An eight for you.</td>', 'This is terrific. Well composed, good DOF too. An eight for you.', '2008-06-29 14:58:32.000000', NULL, 1),
(4790175, 690273, 76335, '<td valign="top">Excellent! Wow. This one has a real sense of depth. And that sky! An eight for you.</td>', 'Excellent! Wow. This one has a real sense of depth. And that sky! An eight for you.', '2008-06-29 14:58:38.000000', NULL, 1),
(4790176, 690825, 76335, '<td valign="top">Abstract, very clean, crisp focus. An eight for you.</td>', 'Abstract, very clean, crisp focus. An eight for you.', '2008-06-29 14:58:49.000000', NULL, 1),
(4790177, 690698, 76335, '<td valign="top">Expertly composed and beautifully processed!</td>', 'Expertly composed and beautifully processed!', '2008-06-29 14:58:59.000000', NULL, 1),
(4790178, 690671, 76335, '<td valign="top">Beautiful! Well exposed and great processing. A seven for you.</td>', 'Beautiful! Well exposed and great processing. A seven for you.', '2008-06-29 14:59:10.000000', NULL, 1),
(4790179, 690535, 76335, '<td valign="top">No single line, but who cares! What a great shot. Love the sepia. A seven for you.</td>', 'No single line, but who cares! What a great shot. Love the sepia. A seven for you.', '2008-06-29 14:59:15.000000', NULL, 1),
(4790180, 690952, 76335, '<td valign="top">Well exposed, very beautiful. The colors are terrific. A seven for you.</td>', 'Well exposed, very beautiful. The colors are terrific. A seven for you.', '2008-06-29 14:59:18.000000', NULL, 1),
(4790181, 691107, 76335, '<td valign="top">Wow, what luck. It''s beautiful. I might have cropped the flowers out. A seven for you.</td>', 'Wow, what luck. It''s beautiful. I might have cropped the flowers out. A seven for you.', '2008-06-29 14:59:22.000000', NULL, 1),
(4790182, 690973, 76335, '<td valign="top">Excellent. The centered horizong really makes this and combined with the lighting and colors, gives it some real depth. A seven for you.</td>', 'Excellent. The centered horizong really makes this and combined with the lighting and colors, gives it some real depth. A seven for you.', '2008-06-29 14:59:26.000000', NULL, 1),
